class Solution {
public:
    int maxFrequencyScore(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        unordered_map<int,long long> cnt;
        for (int i = 0; i < k; i++) cnt[nums[i]]++;
        auto pw = [&](long long b, long long e){ long long r = 1; b %= MOD; while (e) { if (e&1) r = r*b%MOD; b = b*b%MOD; e >>= 1; } return r; };
        long long best = 0, cur = 0;
        for (auto& [v, c] : cnt) cur = (cur + pw(v, c)) % MOD;
        best = cur;
        for (int i = k; i < nums.size(); i++) {
            cnt[nums[i]]++; cnt[nums[i-k]]--;
            if (cnt[nums[i-k]] == 0) cnt.erase(nums[i-k]);
            cur = 0;
            for (auto& [v, c] : cnt) cur = (cur + pw(v, c)) % MOD;
            best = max(best, cur);
        }
        return best;
    }
};

