class Solution {
    public int maxFrequencyScore(int[] nums, int k) {
        final long MOD = 1000000007L;
        HashMap<Integer, Long> cnt = new HashMap<>();
        for (int i = 0; i < k; i++) cnt.merge(nums[i], 1L, Long::sum);
        long best = 0, cur = 0;
        for (Map.Entry<Integer, Long> e : cnt.entrySet()) cur = (cur + pw(e.getKey(), e.getValue(), MOD)) % MOD;
        best = cur;
        for (int i = k; i < nums.length; i++) {
            cnt.merge(nums[i], 1L, Long::sum);
            cnt.merge(nums[i-k], -1L, Long::sum);
            if (cnt.get(nums[i-k]) == 0) cnt.remove(nums[i-k]);
            cur = 0;
            for (Map.Entry<Integer, Long> e : cnt.entrySet()) cur = (cur + pw(e.getKey(), e.getValue(), MOD)) % MOD;
            best = Math.max(best, cur);
        }
        return (int) best;
    }
    private long pw(long b, long e, long m) { long r = 1; b %= m; while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; } return r; }
}

