var maxFrequencyScore = function(nums, k) {
    const MOD = 1000000007n, B = MOD;
    const pw = (b, e) => { let r = 1n; b %= B; while (e > 0n) { if (e & 1n) r = r * b % B; b = b * b % B; e >>= 1n; } return r; };
    const cnt = new Map();
    const add = (x, d) => cnt.set(x, (cnt.get(x) || 0n) + BigInt(d));
    for (let i = 0; i < k; i++) add(nums[i], 1);
    let cur = 0n;
    for (const [v, c] of cnt) cur = (cur + pw(BigInt(v), c)) % B;
    let best = cur;
    for (let i = k; i < nums.length; i++) {
        add(nums[i], 1); add(nums[i-k], -1);
        if (cnt.get(nums[i-k]) === 0n) cnt.delete(nums[i-k]);
        cur = 0n;
        for (const [v, c] of cnt) cur = (cur + pw(BigInt(v), c)) % B;
        if (cur > best) best = cur;
    }
    return Number(best);
