        auto pw = [&](long long b, long long e){ long long r = 1; b %= MOD; while (e) { if (e&1) r = r*b%MOD; b = b*b%MOD; e >>= 1; } return r; };
        long long cur = 0;
        for (int i = 0; i < k; i++) cnt[nums[i]]++;
        for (auto& [v, c] : cnt) cur = (cur + pw(v, c)) % MOD;
        long long best = cur;
        for (int i = k; i < nums.size(); i++) {
            int x = nums[i], y = nums[i-k];
            cur = (cur - pw(x, cnt[x]) + pw(x, cnt[x] + 1) + 2 * MOD) % MOD; cnt[x]++;
            cur = (cur - pw(y, cnt[y]) + pw(y, cnt[y] - 1) + 2 * MOD) % MOD; cnt[y]--;
            if (cnt[y] == 0) cnt.erase(y);
            best = max(best, cur);
        }
        return best;
    }
};

