class Solution {
    public int maxFrequencyScore(int[] nums, int k) {
        final long MOD = 1000000007L;
        HashMap<Integer, Long> cnt = new HashMap<>();
        long cur = 0;
        for (int i = 0; i < k; i++) cnt.merge(nums[i], 1L, Long::sum);
        for (Map.Entry<Integer, Long> e : cnt.entrySet()) cur = (cur + pw(e.getKey(), e.getValue())) % MOD;
        long best = cur;
        for (int i = k; i < nums.length; i++) {
            int x = nums[i], y = nums[i-k];
            cur = (cur - pw(x, cnt.getOrDefault(x, 0L)) + pw(x, cnt.getOrDefault(x, 0L) + 1) + 2 * MOD) % MOD;
            cnt.merge(x, 1L, Long::sum);
            long cy = cnt.get(y);
            cur = (cur - pw(y, cy) + pw(y, cy - 1) + 2 * MOD) % MOD;
            if (cy == 1) cnt.remove(y); else cnt.put(y, cy - 1);
            best = Math.max(best, cur);
        }
        return (int) best;
    }
    private long pw(long b, long e) { long r = 1, m = 1000000007L; b %= m; while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; } return r; }
}

