var maxFrequencyScore = function(nums, k) {
    const B = 1000000007n;
    const pw = (b, e) => { let r = 1n; b %= B; while (e > 0n) { if (e & 1n) r = r * b % B; b = b * b % B; e >>= 1n; } return r; };
    const cnt = new Map();
    let cur = 0n;
    for (let i = 0; i < k; i++) cnt.set(nums[i], (cnt.get(nums[i]) || 0n) + 1n);
    for (const [v, c] of cnt) cur = (cur + pw(BigInt(v), c)) % B;
    let best = cur;
    for (let i = k; i < nums.length; i++) {
        const xin = BigInt(nums[i]), xout = BigInt(nums[i-k]);
        const ci = cnt.get(nums[i]) || 0n;
        cur = (cur - pw(xin, ci) + pw(xin, ci + 1n) + 2n * B) % B;
        cnt.set(nums[i], ci + 1n);
        const co = cnt.get(nums[i-k]);
        cur = (cur - pw(xout, co) + pw(xout, co - 1n) + 2n * B) % B;
        if (co === 1n) cnt.delete(nums[i-k]); else cnt.set(nums[i-k], co - 1n);
        if (cur > best) best = cur;
    }
    return Number(best);
};
